css:
/* =========================
   PRINT & SCREEN SETTINGS
   ========================= */

@media screen {
    .print-format {
        width: 210mm;
        margin: 0 auto;
    }
}

@media print {
    .action-banner {
        display: none !important;
    }
}

/* =========================
   BASE PRINT FORMAT
   ========================= */

.print-format {
    font-family: 'Open Sans', sans-serif;
    font-size: 10px;
    color: #000;
    padding: 8px;
    margin: 0;
}

/* =========================
   MAIN CONTAINER
   ========================= */

.wcb-container {
    width: 100%;
    flex:1;
    border: 1px solid #ccc;
    border-radius: 5px;
    padding: 10px;
}

/* =========================
   LETTERHEAD
   ========================= */

.letterhead {
    font-size: 11px;
    padding: 6px;
    border: 1px solid #ccc;
    border-radius: 4px;
    margin-bottom: 6px;
}

/* =========================
   HEADER
   ========================= */

.header {
    width: 100%;
    text-align: center;
    margin: 10px;
}

.header h2 {
    text-align: center;
    font-size: 14px;
    font-weight: 600;
    color: #1e88e5;
    margin: 0;
    text-decoration: underline;
}

/* =========================
   DOCUMENT INFO TABLE
   ========================= */

.doc-table-section {
    border: 1px solid #ccc;
    border-radius: 5px;
    overflow: hidden;
    margin-bottom: 10px;
}

.doc-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
    border: 1px solid #000;
    border-radius: 5px;
    overflow: hidden;
}

.doc-table td {
    border: 1px solid #ccc;
    vertical-align: top;
}

/* Column widths */
.col-a { width: 50%; }
.col-b { width: 25%; }
.col-c { width: 25%; }

/* Labels */
.label {
    background-color: #f5f5f5;
}

/* Address block */
.address {
    line-height: 1.4;
}

/* =========================
   ITEM TABLE
   ========================= */

.item-table-section {
    margin-top: 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
    overflow: hidden;
}

.item-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    border-radius: 5px;
    overflow: hidden;
}

.item-table th,
.item-table td {
    border: 1px solid #000;
    padding: 5px;
    text-align: center;
}

.item-table th {
    background-color: #f2f2f2;
    font-weight: 600;
}

/* Left align descriptive columns */
.item-table td:nth-child(2),
.item-table td:nth-child(3),
.item-table td:nth-child(5),
.item-table td:nth-child(6) {
    text-align: left;
}

/* =========================
   PARAGRAPHS & FOOTER
   ========================= */

p {
    font-size: 10px;
    margin: 5px 0;
}

.footer {
        position: fixed;
        bottom: 10mm;
        width: 100%;
        text-align: center;
        font-size: 9px;
        color: #555;
        padding: 15px;

    }
